package ar.com.miflix.admin

import com.google.gson.*
import org.junit.Assert.*
import org.junit.Test

class CollectionsTest {
    private fun obj(raw:String)=JsonParser.parseString(raw).asJsonObject
    private fun catalog()=obj("""{"schema_version":1,"items":[{"id":"p","tipo":"pelicula","titulo":"Película","tmdb_id":10,"fecha_agregado":"2020-01-01T00:00:00Z","telegram_url":"https://t.me/demo/1","unknown":{"preserve":true}},{"id":"s","tipo":"serie","titulo":"Serie","tmdb_id":10,"temporadas":[{"numero":0,"episodios":[{"numero":1,"telegram_url":"https://t.me/demo/2"}]}]},{"id":"a","tipo":"anime","titulo":"Anime"}]}""")
    private fun draft()=CollectionRules.fresh().apply {addProperty("nombre","Mundo Marvel")}
    private class Store:StateStore {var value:JsonObject?=null;var fail=false;override fun read()=value?.deepCopy();override fun write(state:JsonObject) {if(fail) error("simulated failure");value=state.deepCopy()}}
    @Test fun createsStableUniqueManualCollection() {val d=draft();val out=CollectionRules.save(CollectionRules.empty(),d,null);assertEquals(d.text("id"),CollectionRules.list(out).single().text("id"));assertNotEquals(d.text("id"),draft().text("id"))}
    @Test fun renamePreservesIdentityOriginAndUnknownFields() {val d=draft().apply{add("future",obj("""{"a":1}"""))};val root=CollectionRules.save(CollectionRules.empty(),d,null);val next=d.deepCopy().apply{addProperty("nombre","Mi universo")};val saved=CollectionRules.save(root,next,d.text("id"));assertEquals(d.get("future"),CollectionRules.list(saved).single().get("future"));assertEquals(d.text("id"),CollectionRules.list(saved).single().text("id"))}
    @Test fun addsMovieSeriesAndAnimeByStableIdOnly() {val d=CollectionRules.add(draft(),linkedSetOf("p","s","a"),catalog());assertEquals(listOf("p","s","a"),CollectionRules.ids(d));assertFalse(d.toString().contains("telegram"));assertFalse(d.toString().contains("fecha_agregado"))}
    @Test fun doubleTapDoesNotDuplicateMembers() {val d=CollectionRules.add(draft(),setOf("p"),catalog());assertEquals(listOf("p"),CollectionRules.ids(CollectionRules.add(d,setOf("p"),catalog())))}
    @Test fun rejectsAddingForeignTitle() {assertThrows(IllegalArgumentException::class.java){CollectionRules.add(draft(),setOf("foreign"),catalog())}}
    @Test fun removingMemberLeavesWholeCatalogUnchanged() {val c=catalog();val snapshot=c.deepCopy();val d=CollectionRules.add(draft(),setOf("p","s"),c);val removed=CollectionRules.members(d,CollectionRules.ids(d).filter{it!="p"});assertEquals(listOf("s"),CollectionRules.ids(removed));assertEquals(snapshot,c)}
    @Test fun reordersWithoutChangingMembership() {val d=CollectionRules.add(draft(),linkedSetOf("p","s","a"),catalog());assertEquals(listOf("a","p","s"),CollectionRules.ids(CollectionRules.move(CollectionRules.move(d,2,-1),1,-1)))}
    @Test fun cannotMoveBeyondBoundary() {val d=CollectionRules.add(draft(),setOf("p"),catalog());assertThrows(IllegalArgumentException::class.java){CollectionRules.move(d,0,-1)}}
    @Test fun deletingCollectionNeverDeletesTitles() {val c=catalog();val d=CollectionRules.add(draft(),setOf("p"),c);assertTrue(CollectionRules.list(CollectionRules.remove(CollectionRules.save(CollectionRules.empty(),d,null),d.text("id"))).isEmpty());assertEquals(3,CatalogRules.items(c).size)}
    @Test fun oneTitleCanBelongToMultipleCollections() {val d=CollectionRules.add(draft(),setOf("p"),catalog());val e=CollectionRules.add(draft(),setOf("p"),catalog());val r=CollectionRules.save(CollectionRules.save(CollectionRules.empty(),d,null),e,null);assertEquals(2,CollectionRules.list(r).count{"p" in CollectionRules.ids(it)})}
    @Test fun rejectsDuplicateCollectionIds() {val d=draft();assertThrows(IllegalArgumentException::class.java){CollectionRules.save(CollectionRules.save(CollectionRules.empty(),d,null),d,null)}}
    @Test fun rejectsDuplicateMemberIdsOnImport() {val d=draft().apply{add("titulos",JsonArray().apply{add("p");add("p")})};assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(d)}}
    @Test fun refusesChangedIdWhileEditing() {val d=draft();val root=CollectionRules.save(CollectionRules.empty(),d,null);assertThrows(IllegalArgumentException::class.java){CollectionRules.save(root,d.deepCopy().apply{addProperty("id","other")},d.text("id"))}}
    @Test fun blankNameRejected() {assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(draft().apply{addProperty("nombre","  ")})}}
    @Test fun invalidUrlRejectedIncludingCredentialsAndNonHttps() {for(url in listOf("   ","http://x.test/a","https://user:password@x.test/a","javascript:alert(1)","https://x.test/white space")) assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(draft().apply{addProperty("poster_url",url)})}}
    @Test fun optionalImagesAndDescriptionAllowNull() {CollectionRules.validate(draft().apply{add("poster_url",JsonNull.INSTANCE);add("descripcion",JsonNull.INSTANCE)})}
    @Test fun invalidOrderAndVisibilityRejected() {for(value in listOf(JsonPrimitive(-1),JsonPrimitive("3"),JsonPrimitive(1.2))) assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(draft().apply{add("orden",value)})};assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(draft().apply{addProperty("visible","true")})}}
    @Test fun unknownOriginOrVersionCannotBeSilentlyRewritten() {assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(draft().apply{addProperty("origen","new-provider")})};assertThrows(IllegalArgumentException::class.java){CollectionRules.parse(CollectionRules.empty().apply{addProperty("version",2)}.toString())}}
    @Test fun unknownRootAndCollectionPropertiesRoundTrip() {val d=draft().apply{addProperty("future","keep")};val root=CollectionRules.save(CollectionRules.empty().apply{add("future_root",obj("""{"x":[1,2]}"""))},d,null);assertEquals(root,CollectionRules.parse(root.toString()))}
    @Test fun missingCatalogMemberReferencePreservedAcrossEdit() {val d=CollectionRules.members(draft(),listOf("temporarily-absent"));val root=CollectionRules.save(CollectionRules.empty(),d,null);val edited=CollectionRules.add(d,setOf("p"),catalog());assertEquals(listOf("temporarily-absent","p"),CollectionRules.ids(CollectionRules.list(CollectionRules.save(root,edited,d.text("id"))).single()))}
    @Test fun rejectsFullCatalogAsCollectionBackup() {assertThrows(IllegalArgumentException::class.java){CollectionRules.parse(catalog().toString())}}
    @Test fun savedCollectionSurvivesRepositoryRestart() {val s=Store();val d=draft();CollectionRepository(s).save(d,null);assertEquals(d,CollectionRules.list(CollectionRepository(s).data()).single())}
    @Test fun draftAndEditingIdSurviveRestart() {val s=Store();val repo=CollectionRepository(s);val d=draft();repo.save(d,null);repo.stage(d,d.text("id"));val resumed=CollectionRepository(s);assertEquals(d,resumed.draft());assertEquals(d.text("id"),resumed.editingId)}
    @Test fun partialUrlDraftCanBeResumedWithoutLockingSavedCollections() {val s=Store();CollectionRepository(s).stage(draft().apply{addProperty("poster_url","https:")},null);val resumed=CollectionRepository(s);assertTrue(resumed.writable);assertEquals("https:",resumed.draft()!!.text("poster_url"))}
    @Test fun saveRetainsPreviousStateAndUndo() {val s=Store();val repo=CollectionRepository(s);val d=draft();repo.save(d,null);repo.save(d.deepCopy().apply{addProperty("nombre","Edited")},d.text("id"));assertTrue(repo.hasBackup);repo.undo();assertEquals("Mundo Marvel",CollectionRules.list(repo.data()).single().text("nombre"))}
    @Test fun deleteCanBeRestored() {val repo=CollectionRepository(Store());val d=draft();repo.save(d,null);repo.delete(d.text("id"));repo.undo();assertEquals(d,CollectionRules.list(repo.data()).single())}
    @Test fun failedSaveKeepsPreviousStateAndDraft() {val s=Store();val repo=CollectionRepository(s);val d=draft();repo.stage(d,null);val before=s.value!!.deepCopy();s.fail=true;assertThrows(IllegalStateException::class.java){repo.save(d,null)};assertEquals(before,s.value);assertEquals(d,repo.draft());assertTrue(CollectionRules.list(repo.data()).isEmpty())}
    @Test fun failedRestoreAndInvalidBackupDoNotMutateAnything() {val s=Store();val repo=CollectionRepository(s);repo.save(draft(),null);val before=s.value!!.deepCopy();assertThrows(Exception::class.java){repo.restore("bad JSON")};assertEquals(before,s.value);s.fail=true;assertThrows(IllegalStateException::class.java){repo.restore(CollectionRules.empty().toString())};assertEquals(before,s.value)}
    @Test fun unknownStoredSchemaLocksOnlyCollectionsUntilExplicitRestore() {val s=Store();s.value=obj("""{"storage_version":2,"future":"keep"}""");val before=s.value!!.deepCopy();val repo=CollectionRepository(s);assertFalse(repo.writable);assertThrows(IllegalStateException::class.java){repo.save(draft(),null)};assertEquals(before,s.value);repo.restore(CollectionRules.empty().toString());assertTrue(repo.writable)}
    @Test fun exportExcludesDraftAndEnvelopeBackup() {val repo=CollectionRepository(Store());repo.save(draft(),null);repo.stage(draft(),null);val exported=CollectionRules.parse(repo.export());assertEquals(1,CollectionRules.list(exported).size);assertFalse(exported.has("draft"));assertFalse(exported.has("backup"))}
    @Test fun allOperationsPreserveDateTelegramAndMetadata() {val c=catalog();val before=c.deepCopy();val repo=CollectionRepository(Store());val d=CollectionRules.add(draft(),linkedSetOf("p","s","a"),c);repo.save(d,null);repo.restore(repo.export());repo.delete(d.text("id"));repo.undo();assertEquals(before,c)}
    @Test fun tmdbOriginRequiresValidPositiveId() {for(v in listOf(JsonNull.INSTANCE,JsonPrimitive(-1),JsonPrimitive("5"))) assertThrows(IllegalArgumentException::class.java){CollectionRules.validate(draft().apply{addProperty("origen","tmdb");add("tmdb_collection_id",v)})}}
    @Test fun thetvdbArtworkIsExcludedEvenAsCustomUrl() {for(url in listOf("https://artworks.thetvdb.com/banners/test.jpg","https://THETVDB.COM/a.jpg","https://thetvdb.plex.tv/a.jpg")) assertFalse(CollectionRules.validUrl(url));assertTrue(CollectionRules.validUrl("https://my-images.invalid/a.jpg"))}

}
